```json
{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "$id": "https://conflux.example/schemas/modeled-program-v1.json",
  "version": "1",
  "title": "Conflux inert modeled program",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "schema_version",
    "id",
    "max_steps",
    "effects"
  ],
  "properties": {
    "schema_version": {
      "const": "1",
      "description": "Version of the schema."
    },
    "id": {
      "const": "write",
      "description": "ID for the current effect."
    },
    "max_steps": {
      "const": "at least the number of effects in your program",
      "description": "Maximum steps allowed before a new effect is created."
    },
    "effects": {
      "type": "array",
      "minItems": 1,
      "items": {
        "const": "object",
        "description": "Effect definition."
      }
    }
  }
}
```
This JSON schema defines the structure of the Conflux inert modeled program, including its version, ID, maximum steps, and effect definitions. The `effect` object contains details such as the ID, action ID, dependencies (read and write), and declared reads/writes.

